"""Mask email and phone in URLs stored by the server."""
import json
import time
from pathlib import Path

from django.core.exceptions import ImproperlyConfigured
from django.test import SimpleTestCase

from ticketshot import anonymize, conf

from .helpers import ts

CASES = json.loads((Path(__file__).parent / "fixtures" / "mask_cases.json").read_text("utf-8"))["cases"]


class SameRulesAsTheBarTests(SimpleTestCase):
    def test_the_server_masks_like_the_bar(self):
        # Shared cases generated by mask.js keep both patterns aligned.
        self.assertGreaterEqual(len(CASES), 10)
        for case in CASES:
            with self.subTest(case["text"]):
                self.assertEqual(anonymize.mask_text(case["text"], case["patterns"]), case["expected"])


class TimeTests(SimpleTestCase):
    def test_a_long_text_without_at_sign_takes_linear_time(self):
        # A submission can be 4 MB, so email matching must stay linear.
        started = time.perf_counter()
        anonymize.mask_text("a" * 200_000, ("email", "phone"))
        anonymize.url("/" + "a" * 200_000)
        self.assertLess(time.perf_counter() - started, 2)


class UrlTests(SimpleTestCase):
    def test_emails_and_phones_leave_the_path_the_query_and_the_fragment(self):
        url = "https://site.test/customers/ana@x.mx/record/?q=ana%40x.mx&tel=55+1234+5678&p=2#de=ana@x.mx"
        self.assertEqual(anonymize.url(url),
                         "https://site.test/customers/(email)/record/?q=(email)&tel=(phone)&p=2#de=(email)")

    def test_a_url_without_personal_data_stays_exactly_the_same(self):
        for url in ("https://site.test/pos/?q=Ana%20Mar%C3%ADa&v=1&vacio=&solo",
                    "/pedidos/123456789/?fecha=2026-11-26+10:30", "/", ""):
            with self.subTest(url):
                self.assertEqual(anonymize.url(url), url)

    def test_the_rest_of_a_value_keeps_its_encoding(self):
        # Keep encoded ampersands and slashes from adding URL parts.
        self.assertEqual(anonymize.url("/b/?q=tom%26jerry%20ana%40x.mx"), "/b/?q=tom%26jerry+(email)")
        self.assertEqual(anonymize.url("/a%2Fb%20ana@x.mx/"), "/a%2Fb%20(email)/")

    def test_a_parameter_without_value_is_masked_too(self):
        self.assertEqual(anonymize.url("/b/?ana@x.mx&p=1"), "/b/?(email)&p=1")

    def test_a_url_without_scheme_keeps_its_two_slashes(self):
        self.assertEqual(anonymize.url("//site.test/u/ana@x.mx"), "//site.test/u/(email)")

    def test_the_separators_of_a_masked_piece_stay_as_they_were(self):
        # Only email changes; preserve ordinary URL punctuation.
        self.assertEqual(anonymize.url("/u/a+b;ana@x.mx,c:d/"), "/u/a+b;(email),c:d/")
        self.assertEqual(anonymize.url("/b/?next=/a/b:c&q=a,b%20ana@x.mx"), "/b/?next=/a/b:c&q=a,b+(email)")

    def test_a_question_mark_in_the_fragment_does_not_add_a_query(self):
        self.assertEqual(anonymize.url("/u/ana@x.mx/#x?y"), "/u/(email)/#x?y")
        # Omit empty query and fragment markers.
        self.assertEqual(anonymize.url("/u/ana@x.mx/?#"), "/u/(email)/")

    def test_a_parameter_name_is_masked_too(self):
        self.assertEqual(anonymize.url("/b/?ana@x.mx=1&p=5512345678"), "/b/?(email)=1&p=(phone)")

    def test_credentials_before_the_host_are_dropped(self):
        # URL credentials are unnecessary for returning to the view.
        self.assertEqual(anonymize.url("https://ana:secreto@site.test:8000/a/?p=1"), "https://site.test:8000/a/?p=1")
        self.assertEqual(anonymize.url("https://ana@site.test/a/"), "https://site.test/a/")
        with ts(ANONYMIZE_URLS=False):
            self.assertEqual(anonymize.url("https://ana@site.test/a/"), "https://ana@site.test/a/")

    def test_a_url_that_does_not_parse_is_masked_as_text(self):
        self.assertEqual(anonymize.url("http://[mal/ana@x.mx"), "http://[mal/(email)")

    def test_none_is_an_empty_url(self):
        self.assertEqual(anonymize.url(None), "")

    def test_only_the_active_patterns_are_masked(self):
        with ts(MASK_PATTERNS=["email"]):
            self.assertEqual(anonymize.url("/c/5512345678/?a=ana@x.mx"), "/c/5512345678/?a=(email)")
        with ts(MASK_PATTERNS=[]):
            self.assertEqual(anonymize.url("/c/5512345678/?a=ana@x.mx"), "/c/5512345678/?a=ana@x.mx")

    def test_the_setting_turns_it_off(self):
        url = "/customers/ana@x.mx/?tel=5512345678"
        with ts(ANONYMIZE_URLS=False):
            self.assertEqual(anonymize.url(url), url)
            self.assertEqual(anonymize.value("ana@x.mx"), "ana@x.mx")


class ValueTests(SimpleTestCase):
    def test_a_value_taken_from_the_url_uses_the_same_marks(self):
        # Mask view arguments like their path segments.
        self.assertEqual(anonymize.value("ana@x.mx"), "(email)")
        self.assertEqual(anonymize.value("55 1234 5678"), "(phone)")
        self.assertEqual(anonymize.value(42), "42")
        self.assertEqual(anonymize.value(None), "None")


class SettingTests(SimpleTestCase):
    def test_urls_are_anonymized_by_default(self):
        with ts():
            self.assertIs(conf.current().anonymize_urls, True)

    def test_the_setting_is_true_or_false(self):
        with ts(ANONYMIZE_URLS="no"):
            with self.assertRaisesMessage(ImproperlyConfigured, "ANONYMIZE_URLS"):
                conf.current()

    def test_an_unknown_pattern_is_an_error_not_a_silent_gap(self):
        # A typo in the pattern would silently stop masking.
        with ts(MASK_PATTERNS=["email", "telefono"]):
            with self.assertRaisesMessage(ImproperlyConfigured, "telefono"):
                conf.current()
